head.script:
// 항목 데이터(호출마다 새 배열)
scwin.getItems = function(n) {
	var lb = [["축구", "농구", "야구", "배구"], ["피자", "치킨", "햄버거", "양꼬치"], ["모니터", "키보드", "마우스", "노트북"]][n];
	var arr = [];
	for (var i = 0; i < lb.length; i++) {
		arr.push({ "codeLB": lb[i], "codeVL": "" + (i + 1) });
	}
	return arr;
};
scwin.onpageload = function() {
	var types = ["input", "calendar", "checkbox", "select", "autoComplete", "radio", "button", "link"];
	var jsonData = [];
	for (var i = 0; i < types.length; i++) {
		jsonData.push({ "label": types[i], "code": types[i] });
	}
	dlt_select.setJSON(jsonData);
	sel_sample.setJSON(scwin.getItems(0));
	sel_sample2.setJSON(scwin.getItems(1));
	sel_sample3.setJSON(scwin.getItems(2));
	dataList1.setJSON([{
		"col1": "select",
		"col2": "7",
		"col3": "yearMonthDate"
	}, {
		"col1": "select",
		"col2": "6",
		"col3": "yearMonthDateTime"
	}]);
};
scwin.grd_oncellindexchange = function(row, col, oldRow, oldCol) {
	// 해당 컬럼의 nodeset 에 맞는 데이터를 동적으로 조회(데이터 변경)
	sel_sample2.setJSON(scwin.getItems(0));
	sel_sample3.setJSON(scwin.getItems(1));
	sel_sample.setJSON(scwin.getItems(2));
	if (col == 1) {
		var obj = {
			inputType: "autoComplete",
			itemTableType: "gridViewItemset",
			options: {
				viewType: "icon",
				displayMode: "label",
				noResult: "useData",
				selectedData: "false",
				search: "contain",
				searchtarget: "label",
				chooseOptionLabel: "-- 선택 --",
				chooseOptionValue: "",
			},
			visibleRowNum: 10,
			width: 330,
			hideHeader: true,
			nodeset: row % 3 === 0 ? "data:sel_sample" : row % 2 === 0 ? "data:sel_sample2" : "data:sel_sample3",
			label: "codeLB",
			value: "codeVL",
			item: [{
					ref: "codeLB",
					header: "label"
				},
				{
					ref: "codeVL",
					header: "value"
				},
			],
		};
		grd.setCellInputType(row, col, obj);
	}
};
scwin.trigger1_onclick = function(e) {
	dataList1.insertRow(0);
};
